def score_with_native_adapter(values, adapter):
    # Python owns validation; the adapter owns only the narrow scoring call.
    if not all(isinstance(value, int) for value in values):
        raise TypeError('values must be integers')
    try:
        return adapter.score(values)
    except AdapterFailure as error:
        raise RuntimeError('Native scorer failed safely') from error

# AdapterFailure and adapter.score are an interface design sketch,
# not a runnable C-extension implementation.

